{
  "html": `<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <style>
        @page { size: A4; margin: 0; }
        body {
            font-family: 'Helvetica', Arial, sans-serif;
            margin: 0; padding: 0; color: #333; font-size: 12px; line-height: 1.4;
        }
        .header { background-color: #1a4a7c; color: white; display: table; width: 100%; height: 160px; }
        .header-left { display: table-cell; width: 160px; vertical-align: middle; background-color: #fff; border-right: 4px solid #1a4a7c; }
        .header-left img { width: 100%; height: 160px; object-fit: cover; }
        .header-right { display: table-cell; vertical-align: middle; padding: 20px 30px; }
        .header-right h1 { margin: 0 0 10px 0; font-size: 28px; text-transform: uppercase; letter-spacing: 2px; }
        .contact-grid { display: block; font-size: 11px; }
        .container { padding: 30px 40px; }
        h2 { color: #000; font-size: 16px; border-bottom: 2px solid #1a4a7c; margin: 20px 0 10px 0; padding-bottom: 5px; text-transform: uppercase; }
        .row { display: flex; width: 100%; gap: 40px; }
        .column { flex: 1; }
    </style>
</head>
<body>
    <div class="header">
        <div class="header-left">
            <img src="${$json.photo}">
        </div>
        <div class="header-right">
            <h1>${$json.name}</h1>
            <div class="contact-grid">
                <div><b>Phone:</b> ${$json.phone}</div>
                <div><b>Email:</b> ${$json.email}</div>
                <div><b>LinkedIn:</b> ${$json.linkedin || 'N/A'}</div>
                <div><b>GitHub:</b> ${$json.github || 'N/A'}</div>
            </div>
        </div>
    </div>
    <div class="container">
        <h2>Profil</h2>
        <p>${$json.summary}</p>

        <h2>Experience</h2>
        ${$json.experiences.map(exp => `
            <div style="margin-bottom: 15px;">
                <div style="display: flex; justify-content: space-between; font-weight: bold;">
                    <span>${exp.poste_experience} | ${exp.entreprise}</span>
                    <span>${exp.date_debut} – ${exp.date_fin}</span>
                </div>
                <ul><li>${exp.description_experience}</li></ul>
            </div>
        `).join('')}

        <div class="row">
            <div class="column">
                <h2>Compétences</h2>
                <ul>
                    ${$json.skills["Programming Languages"] ? $json.skills["Programming Languages"].map(skill => `<li>${skill}</li>`).join('') : '<li>N/A</li>'}
                </ul>
            </div>
        </div>
    </div>
</body>
</html>`
} 
}}

