<html lang="fr">
<head>
    <meta charset="UTF-8">
    <style>
        @page { size: A4; margin: 20mm; }
        body {
            font-family: 'Times New Roman', Times, serif;
            line-height: 1.5;
            color: #333;
            margin: 0;
            padding: 0;
            font-size: 11pt;
        }
        .header {
            text-align: center;
            border-bottom: 2px solid #000;
            padding-bottom: 10px;
            margin-bottom: 20px;
        }
        .header h1 {
            margin: 0;
            font-size: 24pt;
            text-transform: uppercase;
            letter-spacing: 1px;
        }
        .contact-info {
            margin-top: 5px;
            font-size: 10pt;
        }
        h2 {
            font-size: 14pt;
            text-transform: uppercase;
            border-bottom: 1px solid #ccc;
            margin-top: 20px;
            margin-bottom: 10px;
            color: #000;
        }
        .experience-item {
            margin-bottom: 15px;
        }
        .exp-header {
            display: flex;
            justify-content: space-between;
            font-weight: bold;
        }
        .company-name {
            color: #444;
            font-style: italic;
        }
        ul {
            margin-top: 5px;
            padding-left: 20px;
        }
        .skills-container {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 10px;
        }
        .skill-category {
            font-weight: bold;
        }
    </style>
</head>
<body>

    <div class="header">
        <h1>${$json.name}</h1>
        <div class="contact-info">
            ${$json.phone} | ${$json.email} <br>
            LinkedIn: ${$json.linkedin || 'N/A'} | GitHub: ${$json.github || 'N/A'}
        </div>
    </div>

    <div class="section">
        <h2>Profil Professionnel</h2>
        <p>${$json.summary}</p>
    </div>

    <div class="section">
        <h2>Expérience Professionnelle</h2>
        ${$json.experiences.map(exp => `
            <div class="experience-item">
                <div class="exp-header">
                    <span>${exp.poste_experience}</span>
                    <span>${exp.date_debut} – ${exp.date_fin}</span>
                </div>
                <div class="company-name">${exp.entreprise}</div>
                <ul>
                    <li>${exp.description_experience}</li>
                </ul>
            </div>
        `).join('')}
    </div>

    <div class="section">
        <h2>Compétences Techniques</h2>
        <div class="skills-container">
            <div>
                <span class="skill-category">Langages:</span> 
                ${$json.skills["Programming Languages"] ? $json.skills["Programming Languages"].join(', ') : 'N/A'}
            </div>
            <div>
                <span class="skill-category">Frameworks:</span> 
                ${$json.skills["Frontend Frameworks"] ? $json.skills["Frontend Frameworks"].join(', ') : 'N/A'}
            </div>
        </div>
    </div>

    <div class="section">
        <h2>Formation</h2>
        <div class="exp-header">
            <span>Master en Informatique</span>
            <span>2023</span>
        </div>
        <div class="company-name">SUPMTI, Rabat</div>
    </div>

</body>
</html>`
} 
}}

